@dataclass
class FileMetadata:
    path: str
    uid: int
    gid: int
    mode: int
    size: int = 0  # File size in bytes
    file_type: str = ""  # File extension (e.g., ".py", ".txt")

    @property
    def file_id(self) -> str:
        # For backward compatibility, compute file_id without relying on stat()
        # since the file may have been deleted
        hashcontent = f"{self.path}-{self.size}"
        return hashlib.sha1(hashcontent.encode()).hexdigest()

